// Independent coefficient-pair field arithmetic, linear Miller chain and linear field DLP reference.
use std::{collections::BTreeSet,fmt::Write as _,fs,io::Write};
type F=(i64,i64);type P=Option<(F,F)>;fn md(x:i64)->i64{x.rem_euclid(61)}fn addf(x:F,y:F)->F{(md(x.0+y.0),md(x.1+y.1))}fn nf(x:F)->F{(md(-x.0),md(-x.1))}fn subf(x:F,y:F)->F{addf(x,nf(y))}fn mf(x:F,y:F)->F{(md(x.0*y.0+59*x.1*y.1),md(x.0*y.1+x.1*y.0))}fn pow(mut x:F,mut n:i64)->F{let mut r=(1,0);while n>0{if n%2==1{r=mf(r,x)}x=mf(x,x);n/=2;}r}fn div(x:F,y:F)->F{assert_ne!(y,(0,0));mf(x,pow(y,3719))}fn enc(x:F)->i64{x.0+61*x.1}
fn neg(p:P)->P{p.map(|(x,y)|(x,nf(y)))}fn on(p:P,a:i64,b:i64)->bool{p.is_none_or(|(x,y)|mf(y,y)==addf(addf(mf(mf(x,x),x),mf((a,0),x)),(b,0)))}
fn plus(p:P,q:P,a:i64)->P{let((x,y),(u,v))=match(p,q){(None,q)=>return q,(p,None)=>return p,(Some(p),Some(q))=>(p,q)};if x==u&&addf(y,v)==(0,0){return None}let m=if x==u{div(addf(mf((3,0),mf(x,x)),(a,0)),mf((2,0),y))}else{div(subf(v,y),subf(u,x))};let z=subf(subf(mf(m,m),x),u);let c=subf(y,mf(m,x));Some((z,nf(addf(mf(m,z),c))))}
fn mul(p:P,n:i64,a:i64)->P{let mut r=None;for _ in 0..n{r=plus(r,p,a)}r}fn chi(p:P)->P{p.map(|(x,y)|(div(x,(59,0)),div(y,(0,59))))}
fn line(p:P,q:P,at:P)->Option<F>{let((x,y),(u,v),(xx,yy))=(p?,q?,at?);if x==u&&addf(y,v)==(0,0){let z=subf(xx,x);return(z!=(0,0)).then_some(z)}let den=if x==u{mf((2,0),y)}else{subf(u,x)};if den==(0,0){return None}let m=if x==u{div(addf(mf((3,0),mf(x,x)),(21,0)),den)}else{div(subf(v,y),den)};let num=subf(subf(yy,y),mf(m,subf(xx,x)));let vert=plus(p,q,21).map_or((1,0),|(z,_)|subf(xx,z));(num!=(0,0)&&vert!=(0,0)).then(||div(num,vert))}
fn miller(p:P,at:P)->Option<F>{p?;at?;let mut r=p;let mut f=(1,0);for _ in 1..31{f=mf(f,line(r,p,at)?);r=plus(r,p,21)}assert_eq!(r,None);Some(f)}fn pair(p:P,q:P)->Option<F>{if p.is_none()||q.is_none(){return Some((1,0))}Some(nf(div(miller(p,q)?,miller(q,p)?)))}fn shifted(p:P,q:P,s:P)->Option<F>{if p.is_none()||q.is_none(){return Some((1,0))}Some(mf(div(miller(p,plus(q,s,21))?,miller(p,s)?),div(miller(q,neg(s))?,miller(q,plus(p,neg(s),21))?)))}
fn group(g:P,a:i64,b:i64)->Vec<P>{let mut set=BTreeSet::new();let mut p=None;for _ in 0..31{assert!(set.insert(p));assert!(on(p,a,b));p=plus(p,g,a);}assert_eq!(p,None);set.into_iter().collect()}
fn point(p:P)->String{match p{None=>"-1 -1".to_string(),Some((x,y))=>format!("{} {}",enc(x),enc(y))}}
fn solve(g:F,value:F)->i64{assert_ne!(g,(1,0));assert_eq!(pow(g,31),(1,0));let mut p=(1,0);for n in 0..31{if p==value{return n}p=mf(p,g);}panic!("finite field log absent")}
fn analyze()->String{assert_eq!(pow((59,0),30),(60,0));let g=Some(((0,0),(10,0)));let u=Some(((37,0),(14,0)));let s=chi(u);assert!(on(g,21,39)&&on(u,23,54)&&on(s,21,39));assert_eq!(mul(g,31,21),None);assert_eq!(mul(s,31,21),None);assert_eq!(s.map(|(x,y)|(pow(x,61),pow(y,61))),neg(s));let src=group(g,21,39);let tw=group(u,23,54);let z=pair(g,s).unwrap();assert_ne!(z,(1,0));assert_eq!(pow(z,31),(1,0));let mut out=format!("CM61PAIR 61 59 21 39 23 54 31\nGEN {} {} {} {}\n",point(g),point(u),point(s),enc(z));let mut shifted_checks=0;
for(i,&a)in src.iter().enumerate(){for(j,&t)in tw.iter().enumerate(){let b=chi(t);assert!(on(b,21,39));assert_eq!(mul(b,31,21),None);assert_eq!(b.map(|(x,y)|(pow(x,61),pow(y,61))),neg(b));let value=pair(a,b).unwrap();assert_eq!(pow(value,31),(1,0));if a.is_some()&&b.is_some(){assert_ne!(value,(1,0));let off=plus(mul(a,2,21),mul(b,2,21),21);assert_eq!(shifted(a,b,off),Some(value));shifted_checks+=1;}writeln!(out,"PAIR {} {} {} {} {} {}",i,j,point(a),point(t),point(b),enc(value)).unwrap();}}
let mut hom=0;for &a in &src{for &b in &src{assert_eq!(pair(plus(a,b,21),s).unwrap(),mf(pair(a,s).unwrap(),pair(b,s).unwrap()));hom+=1;}}let mut lifts=0;for &a in &tw{for &b in &tw{assert_eq!(chi(plus(a,b,23)),plus(chi(a),chi(b),21));lifts+=1;}}
for(i,&q)in src.iter().enumerate(){let value=pair(q,s).unwrap();let k=solve(z,value);assert_eq!(mul(g,k,21),q);writeln!(out,"REC {} {} {} {}",i,point(q),enc(value),k).unwrap();}
let off=plus(mul(g,2,21),mul(s,2,21),21);assert_eq!(shifted(g,g,off),Some((1,0)));assert!(pair(g,g).is_none());let wrong=Some(((59,0),(0,0)));let lift=chi(wrong);assert!(on(wrong,23,54)&&on(lift,21,39));assert!(mul(lift,31,21).is_some());writeln!(out,"SAME 1 0 {}\nWRONG {} {}\nCHECK 961 {} {} {} 31\nDEGREE NA",point(off),point(wrong),point(lift),shifted_checks,hom,lifts).unwrap();out}
fn main(){let a:Vec<_>=std::env::args().collect();if a.len()!=3{std::process::exit(2)}let r=std::panic::catch_unwind(||{let expected=analyze();let raw=fs::read_to_string(&a[1]).unwrap();assert!(raw==expected,"full F61 pairing/domain/source-scalar replay differs");let result="{\"source_points\":31,\"twist_points\":31,\"pairings\":961,\"nontrivial_pairings\":900,\"shifted_checks\":900,\"source_hom_pairs\":961,\"twist_lift_hom_pairs\":961,\"original_scalar_recoveries\":31,\"nonidentity_targets\":30,\"matrix_degree\":null,\"signed_verdict\":false}\n";fs::OpenOptions::new().write(true).create_new(true).open(&a[2]).unwrap().write_all(result.as_bytes()).unwrap();});if r.is_err(){std::process::exit(101)}}
